assert.equal(roundRatio(-15n, 10n), -2);
assert.equal(roundRatio(-25n, 10n), -2);
assert.equal(roundRatio(1n, 3n), 0);
assert.equal(roundRatio(2n, 3n), 1);
assert.equal(roundRatio(-2n, 3n), -1);
assert.ok(Object.is(roundRatio(0n, 7n), 0));

// no precision loss for huge numerators
const big = (10n ** 30n) * 2n + 1n; // ...001 / 2 -> ...000 (half-even to even)
assert.equal(roundRatio(big, 2n * (10n ** 21n)), Number(10n ** 9n)); // 2000000000.5 -> 2000000000
// unsafe result rejected
assert.throws(() => roundRatio(BigInt(Number.MAX_SAFE_INTEGER) * 2n + 1n, 1n), RangeError);
assert.throws(() => roundRatio(1n, 0n), RangeError);
assert.throws(() => roundRatio(1, 2n), TypeError);

// ordered discounts: percent then fixed
let r = buildInvoice({ currency: 'USD', lines: [{ unitCents: 105, taxBps: 1000, discounts: [{ type: 'percent', rateBps: 5000 }, { type: 'fixed', amountCents: 10 }] }] });
assert.equal(r.lines[0].netCents, 43);
// fixed then percent (reversed order) must differ
r = buildInvoice({ currency: 'USD', lines: [{ unitCents: 105, discounts: [{ type: 'fixed', amountCents: 10 }, { type: 'percent', rateBps: 5000 }] }] });
assert.equal(r.lines[0].netCents, 47); // 95 - round(47.5)=48 -> 47

// credits: percent reduces credit magnitude; fixed never touches credits
r = buildInvoice({ currency: 'USD', lines: [
  { unitCents: -100, taxBps: 1000, discounts: [{ type: 'percent', rateBps: 5000 }, { type: 'fixed', amountCents: 500 }] },
] });
assert.equal(r.lines[0].netCents, -50);
assert.equal(r.lines[0].taxCents, -5);

// invoice tax mode with grouping and allocation
r = buildInvoice({ currency: 'USD', taxMode: 'invoice', lines: [
  { unitCents: 105, taxBps: 1000 }, { unitCents: 105, taxBps: 1000 },
] });
assert.equal(r.taxCents, 21); // 210*0.1 = 21 exact, split 11/10
assert.deepEqual(r.lines.map(l => l.taxCents).sort((a,b)=>a-b), [10, 11]);

// invoice-level discount allocated across positive balances, credit excluded
r = buildInvoice({ currency: 'USD', discounts: [{ type: 'percent', rateBps: 1000 }], lines: [
  { unitCents: 100 }, { unitCents: 200 }, { unitCents: -50 },
] });
assert.equal(r.netCents, 100 + 200 - 30 - 50);
assert.equal(r.lines[2].netCents, -50);

// empty invoice
r = buildInvoice({ currency: 'USD', lines: [] });
assert.deepEqual([r.subtotalCents, r.discountCents, r.netCents, r.taxCents, r.totalCents], [0,0,0,0,0]);
console.log('all sanity checks passed');
